-- ======================================================================
-- VERIFICACION RAPIDA: cantidad total actual por tabla
-- ======================================================================
SELECT t.name AS Tabla, SUM(p.rows) AS TotalFilas
FROM sys.tables t
JOIN sys.partitions p ON t.object_id = p.object_id AND p.index_id IN (0,1)
GROUP BY t.name
ORDER BY t.name;
GO